package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"log"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"sync"
	"time"
)

const (
	auditLogDir   = "/var/log/ci-audit"
	artifactDir   = "/var/ci/artifacts"
	maxBuildSize  = 50 * 1024 * 1024
)

type AuditEntry struct {
	Timestamp time.Time
	Action    string
	User      string
	Resource  string
	Status    string
}

type PipelineServer struct {
	mu       sync.Mutex
	auditLog *os.File
	builds   map[string]*BuildContext
}

type BuildContext struct {
	ID        string
	User      string
	Started   time.Time
	TempDir   string
	Artifacts []string
}

func generateSecureToken(n int) string {
	bytes := make([]byte, n)
	if _, err := rand.Read(bytes); err != nil {
		log.Fatalf("failed to generate secure token: %v", err)
	}
	return hex.EncodeToString(bytes)
}

// sanitizeLogField removes newline, carriage return, and delimiter characters
// from audit-log fields to prevent log injection / forged entries (CWE-117).
func sanitizeLogField(s string) string {
	replacer := strings.NewReplacer(
		"\n", " ",
		"\r", " ",
		"|", "_",
	)
	return replacer.Replace(s)
}

func NewPipelineServer() (*PipelineServer, error) {
	if err := os.MkdirAll(auditLogDir, 0750); err != nil {
		return nil, fmt.Errorf("failed to create audit log dir: %w", err)
	}
	if err := os.MkdirAll(artifactDir, 0750); err != nil {
		return nil, fmt.Errorf("failed to create artifact dir: %w", err)
	}

	logPath := filepath.Join(auditLogDir, "pipeline-audit.log")
	f, err := os.OpenFile(logPath, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0640)
	if err != nil {
		return nil, fmt.Errorf("failed to open audit log: %w", err)
	}

	return &PipelineServer{
		auditLog: f,
		builds:   make(map[string]*BuildContext),
	}, nil
}

func (ps *PipelineServer) writeAudit(entry AuditEntry) error {
	ps.mu.Lock()
	defer ps.mu.Unlock()
	line := fmt.Sprintf("%s|%s|%s|%s|%s\n",
		entry.Timestamp.UTC().Format(time.RFC3339),
		sanitizeLogField(entry.Action),
		sanitizeLogField(entry.User),
		sanitizeLogField(entry.Resource),
		sanitizeLogField(entry.Status))
	_, err := ps.auditLog.WriteString(line)
	return err
}

func (ps *PipelineServer) createBuildWorkspace(user string) (*BuildContext, error) {
	buildID := generateSecureToken(16)

	// Create a temporary workspace for the build
	// Using os.MkdirTemp which creates the directory with 0700 atomically
	tempBase := filepath.Join(os.TempDir(), "ci-pipeline")
	if err := os.MkdirAll(tempBase, 0700); err != nil {
		return nil, fmt.Errorf("failed to create temp base: %w", err)
	}

	buildDir, err := os.MkdirTemp(tempBase, buildID+"-")
	if err != nil {
		return nil, fmt.Errorf("failed to create build dir: %w", err)
	}

	ctx := &BuildContext{
		ID:      buildID,
		User:    user,
		Started: time.Now(),
		TempDir: buildDir,
	}

	ps.mu.Lock()
	ps.builds[buildID] = ctx
	ps.mu.Unlock()

	ps.writeAudit(AuditEntry{
		Timestamp: time.Now(),
		Action:    "BUILD_START",
		User:      user,
		Resource:  buildID,
		Status:    "OK",
	})

	return ctx, nil
}

func (ps *PipelineServer) storeArtifact(buildID string, data io.Reader) (string, error) {
	ps.mu.Lock()
	ctx, exists := ps.builds[buildID]
	ps.mu.Unlock()

	if !exists {
		return "", fmt.Errorf("build %s not found", buildID)
	}

	artifactName := fmt.Sprintf("artifact-%s-%d", buildID[:8], time.Now().UnixNano())
	// Write artifact to the build's temp directory first for processing
	// Use os.CreateTemp for secure temp file creation with restricted permissions
	tmpFile, err := os.CreateTemp(ctx.TempDir, artifactName+"-*")
	if err != nil {
		return "", fmt.Errorf("failed to create temp artifact: %w", err)
	}
	tempArtifactPath := tmpFile.Name()

	// Explicitly set restrictive permissions
	if err := tmpFile.Chmod(0600); err != nil {
		tmpFile.Close()
		os.Remove(tempArtifactPath)
		return "", fmt.Errorf("failed to set artifact permissions: %w", err)
	}

	written, err := io.Copy(tmpFile, io.LimitReader(data, maxBuildSize))
	tmpFile.Close()
	if err != nil {
		os.Remove(tempArtifactPath)
		return "", fmt.Errorf("failed to write artifact: %w", err)
	}

	// Move to final artifact storage
	finalPath := filepath.Join(artifactDir, artifactName)
	if err := os.Rename(tempArtifactPath, finalPath); err != nil {
		os.Remove(tempArtifactPath)
		return "", fmt.Errorf("failed to finalize artifact: %w", err)
	}

	// Ensure final artifact has correct permissions
	if err := os.Chmod(finalPath, 0640); err != nil {
		os.Remove(finalPath)
		return "", fmt.Errorf("failed to set final permissions: %w", err)
	}

	ctx.Artifacts = append(ctx.Artifacts, finalPath)

	ps.writeAudit(AuditEntry{
		Timestamp: time.Now(),
		Action:    "ARTIFACT_STORE",
		User:      ctx.User,
		Resource:  fmt.Sprintf("%s:%s:%d", buildID, artifactName, written),
		Status:    "OK",
	})

	return finalPath, nil
}

func (ps *PipelineServer) handleUpload(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	user := r.Header.Get("X-CI-User")
	if user == "" {
		http.Error(w, "unauthorized", http.StatusUnauthorized)
		return
	}

	buildID := r.Header.Get("X-Build-ID")
	if buildID == "" {
		// Start a new build
		ctx, err := ps.createBuildWorkspace(user)
		if err != nil {
			http.Error(w, "internal error", http.StatusInternalServerError)
			return
		}
		buildID = ctx.ID
	}

	artifactPath, err := ps.storeArtifact(buildID, r.Body)
	if err != nil {
		http.Error(w, "upload failed", http.StatusInternalServerError)
		return
	}

	w.Header().Set("Content-Type", "application/json")
	fmt.Fprintf(w, `{"build_id":"%s","artifact":"%s"}`, buildID, filepath.Base(artifactPath))
}

func main() {
	server, err := NewPipelineServer()
	if err != nil {
		log.Fatalf("Failed to start pipeline server: %v", err)
	}
	defer server.auditLog.Close()

	http.HandleFunc("/api/v1/upload", server.handleUpload)

	log.Println("CI Pipeline server starting on :8443")
	log.Fatal(http.ListenAndServeTLS(":8443", "/etc/ci/tls/cert.pem", "/etc/ci/tls/key.pem", nil))
}
